  Definition emw (K : midK) (estrp ppl fl2 a8v v440 : Z) (oc : list Z) (m : word -> option byte) (fc : bv 32) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 9 "SG0!1,2|600;!1+^F0|30;!1+^F!1,22|500;|21;!1,25|32;!2'10/sp;!2'^Q0,@!1'_D#9!1,^M+_5|8a8;}3}<}U!2'^K+6#3!2'^K+6/o0;!1'_J#9|22;!1'_E#9!1'_L#9|10;$K;R+_=$estrp;R+6$ppl;R+6$fl2;R+6$a8v;R+6$v440;R+6$oc;R!1+7+6$m;R%~R1!1+=3$fc;R!1+^F!1,24!2+J!2'_>#2!1'_?#9!2+J!1'^Z#1!2+J%k;R!1+^F6%~R!1'^B!3+9+6!2'16#1!1,57!3+91!2'_4!1'_@#;#2!2'_4/F;#2!2+J!4'_8'^U#2!2'08!1,_9|9020;!3,^I+_5!1,_79!3,^I+_5!2,_6}X!1'_A#9!3,^I+_5!1,_7!2'^Q0/w;!3,^I+_5!1,_7!2'^Q0#8!3,^I+_5!1,_7!2'^Q0#7!3,^I+_5!1,_7!2'^Q0#6!3,^I+_5!1,_7!2'^Q0!1,5|F2c18d0;!3,^I+_5!1,_7!2'^Q0#5!3,^I+_5!1,_7!2'^Q0:!3,^I+_5!1,_7!2'^Q0#4!3,^I+_5!1,_7!2'^Q0'^L;!2+J!4'_8'^U#2!2'08!1,_9<!3,^I+_5!1,_F9!3,^I+_5!2,_6=!1'_G#9;!2+J!4'_8'^U#2!2'08!1,_9|8a1;!3,^I+_5!2,_6>!1'_H#9;!2+J!4'_8'^U#2!2'08!1,_9|895;!3,^I+_5!2,_6?!1'_I#9;!2+J!9'^\#2'^L/fl0;/j1;/j2;/lbfw;/B;!1'_0#3!3'_13!2'_2@A/junk0;!2+J!2+`KA@!2+J!2+J!2'W,@B!2'WB!1,5C!2+J!2+J!2'W,@D!2'WD!1,5,N!2+J!3+9+6:!2'0!1,5|@3ed7;B!2+J!2'W,@E!2'XE!2'4!1,5F!1,5|44;").
  Ltac dest_emw2 H :=
    let FI := fresh "FI" in let FRM := fresh "FRM" in let HFt := fresh "HFt" in let FRs := fresh "FRs" in let E2 := fresh "E2" in
    let EB := fresh "EB" in let BF := fresh "BF" in let WF := fresh "WF" in let LOC := fresh "LOC" in
    let Hpre := fresh "Hpre" in let Hpl := fresh "Hpl" in let Hpfx := fresh "Hpfx" in let Hp1 := fresh "Hp1" in
    destruct H as (FI & FRM & HFt & FRs & E2 & EB & BF & WF & LOC & Hpre & Hpl & Hpfx & Hp1);
    cbn [K_pad K_jk40 K_jk8 K_jk3 K_jk12 K_jk37 K_p1 K_prefix K_pl K_plz K_pfx K_Ft] in *;
